scriptdefs
= Route121_SafariZoneEntrance_EventScript_ExitSafariZone
lockall
applymovement LOCALID_PLAYER Route121_SafariZoneEntrance_Movement_ExitSafariZone
waitmovement 0
setvar VAR_SAFARI_ZONE_STATE 0
releaseall
end
= Route121_SafariZoneEntrance_EventScript_EntranceCounterTrigger
lockall
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterUp
waitmovement 0
showmoneybox 0 0
msgboxyesno	Welcome to the SAFARI ZONE!All you can catch for just ¥500! Would you like to play a SAFARI Game?
goto_if_eq VAR_RESULT YES Route121_SafariZoneEntrance_EventScript_TryEnterSafariZone
msgbox	Okay. Bitte spiel ein anderes Mal!
goto Route121_SafariZoneEntrance_EventScript_MovePlayerBackFromCounter
end
= Route121_SafariZoneEntrance_EventScript_MovePlayerBackFromCounter
closemessage
hidemoneybox
applymovement LOCALID_PLAYER Route121_SafariZoneEntrance_Movement_BackAwayFromCounter
waitmovement 0
releaseall
end
= Route121_SafariZoneEntrance_EventScript_TryEnterSafariZone
checkitem ITEM_POKEBLOCK_CASE
goto_if_eq VAR_RESULT 0 Route121_SafariZoneEntrance_EventScript_NoPokeblockCase
call Route121_SafariZoneEntrance_EventScript_CheckHasRoomForPokemon
checkmoney 500
goto_if_eq VAR_RESULT 0 Route121_SafariZoneEntrance_EventScript_NotEnoughMoney
playse SE_SHOP
msgbox	Das macht dann 500 ¥, bitte.
removemoney 500
updatemoneybox
msgbox	Hier sind deine SAFARI BALLS.
playfanfare MUS_OBTAIN_ITEM
msgbox	PLAYER erhielt 30 SAFARI BALLS.
waitfanfare
msgbox	Wir sagen dir Bescheid, wenn dein Spiel vorbei ist.Bis dahin viel Vergnügen! Auf geht's zu deinem wilden Ausflug!
closemessage
hidemoneybox
applymovement LOCALID_PLAYER Route121_SafariZoneEntrance_Movement_EnterSafariZone
waitmovement 0
special EnterSafariMode
setvar VAR_SAFARI_ZONE_STATE 2
clearflag FLAG_GOOD_LUCK_SAFARI_ZONE
warp SafariZone_South 32 33
waitstate
end
= Route121_SafariZoneEntrance_EventScript_NotEnoughMoney
msgbox	Du hast nicht genug Geld dabei. Tut mir leid.
goto Route121_SafariZoneEntrance_EventScript_MovePlayerBackFromCounter
end
= Route121_SafariZoneEntrance_EventScript_CheckHasRoomForPokemon
getpartysize
goto_if_ne VAR_RESULT PARTY_SIZE Route121_SafariZoneEntrance_EventScript_HasRoomForPokemon
specialvar VAR_RESULT ScriptCheckFreePokemonStorageSpace
goto_if_eq VAR_RESULT 1 Route121_SafariZoneEntrance_EventScript_HasRoomForPokemon
msgbox	Entschuldigung! Deine PC-BOX ist voll.
goto Route121_SafariZoneEntrance_EventScript_MovePlayerBackFromCounter
end
= Route121_SafariZoneEntrance_EventScript_HasRoomForPokemon
return
= Route121_SafariZoneEntrance_EventScript_NoPokeblockCase
msgbox	Entschuldigung! Du scheinst kein CASE dabeizuhaben.Dein SAFARI-Spiel wird viel ergiebiger, wenn du ein S verwendest.Bitte komm mit einem CASE zurück.Ein CASE erhältst du in der LILYCOVE CONTEST HALL.
goto Route121_SafariZoneEntrance_EventScript_MovePlayerBackFromCounter
end
= Route121_SafariZoneEntrance_EventScript_InfoAttendant
lock
faceplayer
msgboxyesno	Welcome to the SAFARI ZONE! Is it your first time here?
goto_if_eq VAR_RESULT YES Route121_SafariZoneEntrance_EventScript_FirstTimeInfo
msgbox	Komm herein und genieße die SAFARI ZONE!
release
end
= Route121_SafariZoneEntrance_EventScript_FirstTimeInfo
msgbox	Wenn du die SAFARI ZONE betrittst, startest du mit 30 SAFARI BALLS zum Fangen von POKéMON.Das SAFARI-Spiel endet, wenn dir die SAFARI BALLS ausgehen oder wenn du 500 Schritte gegangen bist.Komm herein und genieße die SAFARI ZONE!
release
end
= Route121_SafariZoneEntrance_EventScript_WelcomeAttendant
msgbox	Willkommen in der SAFARI ZONE!Hier kannst du viele Arten von POKéMON erleben, die in HOENN nur selten zu sehen sind.Und du siehst sie wild und ungezähmt in ihren natürlichen Lebensräumen.Außerdem haben wir unsere Tore für POKéMON-TRAINER geöffnet.Wir laden dich ein, POKéMON zu fangen und zu behalten!Komm herein und genieße die SAFARI ZONE!
end
